// Farm-owned startup adapter for the pond viewer only.
// Will, 2026-10-04: cap pixel ratio <= 1.5, and one on low-power devices.
// Append to the generated DT deployment registry, a synchronous classic script.
(() => {
  const deployment = globalThis.DT_DEPLOYMENT;
  const selected = new URLSearchParams(globalThis.location?.search ?? '').get('site')
    || deployment?.defaultSite;
  if (!deployment?.sites?.[selected] || !/^yilan-pond(?:$|-)/.test(selected)) return;
  const nav = globalThis.navigator ?? {};
  const lowPower = nav.connection?.saveData === true
    || (Number.isFinite(nav.deviceMemory) && nav.deviceMemory > 0 && nav.deviceMemory <= 4)
    || (Number.isFinite(nav.hardwareConcurrency) && nav.hardwareConcurrency > 0 && nav.hardwareConcurrency <= 4);
  const phone = globalThis.matchMedia?.('(pointer: coarse)').matches
    || globalThis.matchMedia?.('(max-width: 600px)').matches;
  const cap = phone || lowPower ? 1 : 1.5;
  // Preserve the native getter so zoom or monitor changes still produce a real
  // value before it is capped. The descriptor belongs only to this viewer realm.
  const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'devicePixelRatio');
  const nativeRatio = globalThis.devicePixelRatio;
  const readNative = descriptor?.get ? () => descriptor.get.call(globalThis) : () => nativeRatio;
  Object.defineProperty(globalThis, 'devicePixelRatio', {
    configurable: true,
    enumerable: descriptor?.enumerable ?? true,
    get() {
      const ratio = readNative();
      return Math.min(Number.isFinite(ratio) && ratio > 0 ? ratio : 1, cap);
    },
  });
  globalThis.FARM_POND_RENDER_PROFILE = Object.freeze({pixelRatioCap: cap, phone: !!phone, lowPower});
})();

